def _background(fn, label):
    def run(set_progress, *args):
        try:
            return fn(lambda msg: set_progress([msg]), *args)
        except Exception as e:
            LOG.exception("%s failed", label)
            set_progress([f"⚠ {label} failed: {e}"])
            return {"ok": False, "error": str(e)}
    return run


